// Valoria.h: systems ported from VALORIA (Twin Realms).
//
// Gear bonuses: VALORIA gear can carry STR, DEX, VIT, INT, MAG, flat HP and MP, defence (jewellery)
// and critical chance while equipped. Helbreath items can't express several of these at once, so the
// bonuses live in ..\configs\valoria_gear.txt (generated by tools/valoria_port/build_items.py),
// keyed by item name. CGame::CalcTotalItemEffect adds them up into CClient::m_gear*.
#pragma once

struct ValoriaGearBonus
{
	int str, dex, vit, iint, mag, hp, mp, def, crit;
};

// Reads the gear bonus table. Returns the number of items read, or -1 if the file is missing.
int Valoria_LoadGear(const char * pFileName);

// The bonuses of the item with this name, or NULL if it has none.
const ValoriaGearBonus * Valoria_FindGear(const char * pItemName);

// Recipes: VALORIA's forging, alchemy and crafting recipes replace Helbreath's (BuildItem.cfg, Potion.cfg,
// CraftItem.cfg, generated by tools/valoria_port/build_recipes.py). What Helbreath's files can't hold,
// the character level, gold fee and number of items made, is in ..\configs\valoria_recipes.txt, keyed by
// the name of the item the recipe makes.
struct ValoriaRecipe
{
	int level, gold, qty;
};

// Reads the recipe table. Returns the number of recipes read, or -1 if the file is missing.
int Valoria_LoadRecipes(const char * pFileName);

// The level, gold and quantity of the recipe that makes this item, or NULL if there is none.
const ValoriaRecipe * Valoria_FindRecipe(const char * pItemName);
